window.docContents[97].resolve({"/#PropertyKindCalculus-Blueprint--Extensivity":{"contents":"Dybkær §13.5 distinguishes extensive kinds (whose value over a whole is the sum\nover disjoint parts) from kinds where that fails. This is a quantified arithmetic\nlaw over the mereology of systems — again something a description logic cannot\nstate. This chapter is planned.\n\n\n\n","context":"PropertyKindCalculus Blueprint","header":"8. Extensivity","id":"/#PropertyKindCalculus-Blueprint--Extensivity"}});